import React, { useEffect, useState } from "react";

function Threats() {
  const [threats, setThreats] = useState([]);

  useEffect(() => {
    fetch("http://127.0.0.1:8000/threats/live")
      .then((res) => res.json())
      .then((data) => {
        setThreats(data.threats);
      });
  }, []);

  return (
    <div>
      <h1>Threats</h1>
      {threats.map((t, index) => (
        <div key={index}>
          {t.type} — {t.severity}
        </div>
      ))}
    </div>
  );
}

export default Threats;
